type Tone = "primary" | "secondary" | "ghost" | "danger";

function useRouter() {
  const [path, setPath] = useState(() => window.location.pathname || "/");
  useEffect(() => {
    const onPop = () => setPath(window.location.pathname || "/");
    window.addEventListener("popstate", onPop);
    return () => window.removeEventListener("popstate", onPop);
  }, []);
  const go = (next: string) => {
    window.history.pushState({}, "", next);
    setPath(next);
    window.scrollTo({ top: 0, behavior: "smooth" });
  };
  return { path, go };
}

function Logo({ compact = false, onClick }: { compact?: boolean; onClick?: () => void }) {
  return (
    <button onClick={onClick} className="focus-ring flex items-center gap-3 text-left" aria-label="NovaCare home">
      <span className="grid h-9 w-9 place-items-center rounded-xl border border-[#4db5dd]/30 bg-[#0b151e] shadow-[0_0_28px_rgba(62,177,221,.18)]">
        <span className="relative block h-4 w-4"><span className="absolute left-[6px] top-0 h-4 w-[3px] rounded-full bg-[#63c5e9]" /><span className="absolute left-0 top-[6px] h-[3px] w-4 rounded-full bg-[#63c5e9]" /></span>
      </span>
      {!compact && <span className="text-[15px] font-semibold tracking-[-.03em] text-[#eaf7fc]">NovaCare<span className="text-[#62c6eb]">.</span></span>}
    </button>
  );
}

function ActionButton({ tone = "primary", className = "", children, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & { tone?: Tone }) {
  const tones: Record<Tone, string> = {
    primary: "bg-[#67c6e8] text-[#06131b] shadow-[0_10px_30px_rgba(64,174,216,.2)] hover:bg-[#8bdbf5]",
    secondary: "border border-[#67c6e8]/25 bg-[#102533] text-[#ccecf5] hover:border-[#67c6e8]/50 hover:bg-[#153344]",
    ghost: "text-[#8da6b4] hover:bg-[#132432] hover:text-[#e6f6fb]",
    danger: "border border-[#ef776e]/30 bg-[#351d20] text-[#ffb4ab] hover:bg-[#462327]",
  };
  return <button {...props} className={`focus-ring interactive inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold disabled:cursor-not-allowed disabled:opacity-45 ${tones[tone]} ${className}`}>{children}</button>;
}

function IconButton({ label, children, className = "", onClick }: { label: string; children: ReactNode; className?: string; onClick?: () => void }) {
  return <button onClick={onClick} aria-label={label} className={`focus-ring interactive grid h-10 w-10 place-items-center rounded-xl border border-[#81bcd0]/15 bg-[#0f1a24]/70 text-[#9fb8c4] hover:text-[#dff5fc] ${className}`}>{children}</button>;
}

