function HowCard({ number, icon: IconComponent, title, copy }: { number: string; icon: Icon; title: string; copy: string }) { return <div className="glass-soft rounded-2xl p-5"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-[#60c2e6]">{number}</span><IconComponent size={17} className="text-[#79b5c9]" /></div><h3 className="mt-10 text-sm font-semibold text-[#e5f4f7]">{title}</h3><p className="mt-2 text-xs leading-5 text-[#8097a3]">{copy}</p></div>; }

