function Login({ role, go }: { role: Role; go: (path: string) => void }) {
  const meta = roleMeta[role]; const IconComponent = meta.icon; const [otp, setOtp] = useState(false);
  const isPatient = role === "patient";
  const submit = () => { if (isPatient && !otp) { setOtp(true); toast.success("A demo verification code was sent"); } else { go(meta.path); } };
  return <main className="grain relative min-h-screen overflow-hidden"><NoiseBackdrop /><div className="container relative z-10 py-7"><div className="flex items-center justify-between"><Logo onClick={() => go("/")} /><button className="focus-ring flex items-center gap-2 text-sm text-[#839ba7] hover:text-white" onClick={() => go("/roles")}><ArrowLeft size={15} /> Change role</button></div><div className="flex min-h-[calc(100vh-110px)] items-center justify-center py-16"><div className="w-full max-w-[440px]"><span className="mx-auto grid h-16 w-16 place-items-center rounded-2xl border border-[#63c6ea]/20 bg-[#123246] text-[#75d1f1] shadow-[0_0_40px_rgba(61,167,208,.16)]"><IconComponent size={28} /></span><div className="mt-7 text-center"><div className="eyebrow">{meta.label} portal</div><h1 className="display-font mt-3 text-5xl tracking-[-.04em] text-[#eaf7fa]">Welcome back.</h1><p className="mt-3 text-sm text-[#879faa]">{isPatient ? (otp ? "Enter the verification code sent to your phone." : "Use your phone number to securely continue.") : meta.description}</p></div><div className="glass mt-9 rounded-3xl p-6 sm:p-8"><div className="space-y-4">{isPatient ? otp ? <div><label className="mb-2 block text-xs font-semibold text-[#a1bbc5]">6-digit verification code</label><input autoFocus inputMode="numeric" maxLength={6} placeholder="•  •  •  •  •  •" className="focus-ring h-14 w-full rounded-xl border border-[#84bfd5]/20 bg-[#0a131b] px-4 text-center text-lg tracking-[.45em] text-[#e8f7fa] placeholder:text-[#59717d]" /></div> : <Field label="Phone number" placeholder="+91 98765 43210" icon={Phone} /> : role === "asha" ? <><Field label="Worker ID" placeholder="ASHA-10248" icon={BadgeCheck} /><Field label="4-digit PIN" placeholder="••••" icon={LockKeyhole} type="password" /></> : <><Field label="Work email" placeholder="doctor@novacare.in" icon={MessageCircle} type="email" /><Field label="Password" placeholder="••••••••" icon={LockKeyhole} type="password" /></>}</div><div className="mt-5 flex items-center justify-between text-xs text-[#78919d]"><label className="flex items-center gap-2"><input type="checkbox" className="accent-[#67c6e8]" /> Remember this device</label>{isPatient ? <button onClick={() => setOtp(false)} className="text-[#67c6e8] hover:text-white">{otp ? "Use another number" : "Need help?"}</button> : <button onClick={() => toast("Password reset is available in the full product.")} className="text-[#67c6e8] hover:text-white">Forgot password?</button>}</div><ActionButton onClick={submit} className="mt-7 w-full py-3.5">{isPatient && !otp ? "Send verification code" : "Continue to portal"}<ArrowRight size={16} /></ActionButton><div className="mt-5 text-center text-[11px] leading-5 text-[#6f8792]">By continuing, you agree to use NovaCare as a health-awareness and record-keeping tool, not a diagnostic service.</div></div><button onClick={() => go("/roles")} className="focus-ring mx-auto mt-7 flex items-center gap-2 text-xs text-[#6f8996] hover:text-white"><ArrowLeft size={13} /> Choose a different portal</button></div></div></div></main>;
}

function Field({ label, placeholder, icon: IconComponent, type = "text" }: { label: string; placeholder: string; icon: Icon; type?: string }) { return <label className="block"><span className="mb-2 block text-xs font-semibold text-[#a1bbc5]">{label}</span><span className="relative block"><IconComponent size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-[#63808c]" /><input type={type} placeholder={placeholder} className="focus-ring h-12 w-full rounded-xl border border-[#84bfd5]/20 bg-[#0a131b] pl-11 pr-4 text-sm text-[#e8f7fa] placeholder:text-[#59717d]" /></span></label>; }

const patientNav = [{ key: "overview", label: "Overview", icon: HomeIcon }, { key: "health-check", label: "Health check", icon: HeartPulse }, { key: "history", label: "History & trends", icon: Activity }, { key: "medications", label: "Medications", icon: Syringe }, { key: "profile", label: "Profile", icon: UserRound }, { key: "settings", label: "Settings", icon: Settings }];
const ashaNav = [{ key: "overview", label: "Overview", icon: HomeIcon }, { key: "patients", label: "Patients", icon: UsersRound }, { key: "add-patient", label: "Add patient", icon: Plus }, { key: "assisted-check", label: "Assisted check", icon: HeartPulse }];
const doctorNav = [{ key: "overview", label: "Overview", icon: HomeIcon }, { key: "patients", label: "Patients", icon: UsersRound }, { key: "heatmap", label: "Heatmap", icon: Map }];

function AppShell({ role, path, go, children }: { role: Role; path: string; go: (path: string) => void; children: ReactNode }) {
  const [open, setOpen] = useState(false); const nav = role === "patient" ? patientNav : role === "asha" ? ashaNav : doctorNav; const active = path.split("/")[2] || "overview"; const meta = roleMeta[role];
  const Nav = () => <div className="flex h-full flex-col"><div className="flex items-center justify-between px-5 py-6"><Logo /><button onClick={() => setOpen(false)} className="focus-ring text-[#77929f] lg:hidden"><X size={18} /></button></div><div className="px-4"><div className="rounded-2xl border border-[#79bcd3]/10 bg-[#0d1b26] p-3"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#174157] text-[#71cbed]"><meta.icon size={17} /></div><div className="min-w-0"><div className="truncate text-xs font-semibold text-[#e3f4f7]">{role === "patient" ? "Ananya Sharma" : role === "asha" ? "Meera Kumari" : "Dr. Arjun Rao"}</div><div className="mt-0.5 text-[10px] text-[#7894a0]">{meta.label}</div></div><ChevronDown size={14} className="ml-auto text-[#66808d]" /></div></div></div><nav className="sidebar-scroll mt-7 flex-1 overflow-y-auto px-3">{nav.map((item) => { const IconComponent = item.icon; const selected = active === item.key; return <button key={item.key} onClick={() => { go(`/${role}/${item.key}`); setOpen(false); }} className={`focus-ring mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm font-medium transition ${selected ? "bg-[#16384b] text-[#a9e5f6] shadow-[inset_3px_0_0_#67c6e8]" : "text-[#7e98a5] hover:bg-[#102431] hover:text-[#d9f0f5]"}`}><IconComponent size={17} strokeWidth={selected ? 2.2 : 1.8} /><span>{item.label}</span>{item.key === "patients" && role === "asha" && <span className="ml-auto rounded-full bg-[#244b5b] px-1.5 py-0.5 text-[9px] text-[#9bd8e8]">24</span>}</button>; })}</nav><div className="border-t border-[#85bdd0]/10 p-4"><button onClick={() => go("/")} className="focus-ring flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-[#7e98a5] transition hover:bg-[#102431] hover:text-[#e7f6fa]"><LogOut size={17} /> Sign out</button><div className="mt-4 flex items-center gap-2 px-3 text-[10px] text-[#5f7985]"><LockKeyhole size={12} /> Private demo environment</div></div></div>;
  return <div className="min-h-screen bg-[#070b12] text-[#e8f1f7]"><aside className={`desktop-sidebar fixed inset-y-0 left-0 z-40 w-[250px] flex-col border-r border-[#88bfd0]/10 bg-[#091119]/95 ${open ? "!flex" : ""}`}><Nav /></aside>{open && <button aria-label="Close navigation" onClick={() => setOpen(false)} className="fixed inset-0 z-30 bg-black/60 lg:hidden" />}{open && <aside className="fixed inset-y-0 left-0 z-40 flex w-[250px] flex-col border-r border-[#88bfd0]/10 bg-[#091119] lg:hidden"><Nav /></aside>}<div className="lg:pl-[250px]"><div className="flex h-[76px] items-center justify-between border-b border-[#88bfd0]/10 px-5 sm:px-8"><div className="flex items-center gap-3"><IconButton label="Open menu" onClick={() => setOpen(true)} className="lg:hidden"><Menu size={19} /></IconButton><div className="hidden text-xs text-[#6f8a97] sm:block">{role === "patient" ? "Patient workspace" : role === "asha" ? "Field workspace" : "Clinical workspace"}<span className="mx-2 text-[#385363]">/</span><span className="text-[#b2c9d2]">{nav.find((item) => item.key === active)?.label || "Overview"}</span></div></div><div className="flex items-center gap-2"><div className="hidden items-center gap-2 rounded-full border border-[#81bdd2]/10 bg-[#0c1720] px-3 py-2 text-xs text-[#78939f] md:flex"><span className="h-1.5 w-1.5 rounded-full bg-[#59d0a3]" /> Demo data environment</div><IconButton label="Notifications" onClick={() => toast("You have no new notifications")}><Bell size={17} /></IconButton><div className="ml-1 grid h-9 w-9 place-items-center rounded-xl border border-[#67bdda]/20 bg-[#173345] text-xs font-semibold text-[#a9e7f4]">{role === "doctor" ? "AR" : role === "asha" ? "MK" : "AS"}</div></div></div><main className="min-h-[calc(100vh-76px)] px-5 py-8 sm:px-8 lg:px-10">{children}</main></div></div>;
}

function SectionHeading({ eyebrow, title, copy, action }: { eyebrow?: string; title: string; copy?: string; action?: ReactNode }) { return <div className="mb-7 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"> <div>{eyebrow && <div className="eyebrow mb-2">{eyebrow}</div>}<h1 className="text-3xl font-semibold tracking-[-.045em] text-[#e6f4f7] sm:text-[2.35rem]">{title}</h1>{copy && <p className="mt-2 max-w-xl text-sm leading-6 text-[#8099a5]">{copy}</p>}</div>{action}</div>; }

function StatCard({ icon: IconComponent, label, value, unit, detail, tone = "blue", children }: { icon: Icon; label: string; value: string; unit?: string; detail: string; tone?: "blue" | "green" | "amber"; children?: ReactNode }) { const tones = { blue: "bg-[#153746] text-[#69c9eb]", green: "bg-[#173b32] text-[#73dcae]", amber: "bg-[#3a2d1e] text-[#efc277]" }; return <div className="glass interactive rounded-2xl p-5"><div className="flex items-start justify-between"><span className={`grid h-10 w-10 place-items-center rounded-xl ${tones[tone]}`}><IconComponent size={19} /></span>{children || <MoreHorizontal size={17} className="text-[#5d7886]" />}</div><div className="mt-6 text-xs text-[#829ba7]">{label}</div><div className="mt-2 flex items-baseline gap-2"><span className="text-[2.1rem] font-semibold tracking-[-.06em] text-[#e9f7f9]">{value}</span>{unit && <span className="text-sm text-[#8da4ae]">{unit}</span>}</div><div className="mt-2 flex items-center gap-2 text-xs text-[#79dbad]"><span className="h-1.5 w-1.5 rounded-full bg-current" />{detail}</div></div>; }

function TrendChart({ compact = false, amber = false }: { compact?: boolean; amber?: boolean }) { return <div className={`relative overflow-hidden ${compact ? "h-12 w-28" : "h-56 w-full"}`}><svg viewBox="0 0 500 180" preserveAspectRatio="none" className="h-full w-full"><defs><linearGradient id={amber ? "amberFill" : "blueFill"} x1="0" x2="0" y1="0" y2="1"><stop offset="0" stopColor={amber ? "#efbd69" : "#61c7e9"} stopOpacity=".25" /><stop offset="1" stopColor={amber ? "#efbd69" : "#61c7e9"} stopOpacity="0" /></linearGradient></defs>{!compact && <><line x1="0" x2="500" y1="42" y2="42" stroke="#a8c9d4" strokeOpacity=".1" /><line x1="0" x2="500" y1="90" y2="90" stroke="#a8c9d4" strokeOpacity=".1" /><line x1="0" x2="500" y1="138" y2="138" stroke="#a8c9d4" strokeOpacity=".1" /></>}<path d={amber ? "M0 112 C28 106 38 120 67 92 S110 95 137 106 S179 100 209 68 S253 71 281 86 S322 74 347 58 S392 67 420 45 S461 56 500 31 L500 180 L0 180 Z" : "M0 104 C28 120 45 91 68 98 S108 74 134 91 S175 60 205 76 S236 64 265 68 S303 45 331 65 S367 52 393 56 S439 26 468 43 S488 34 500 37 L500 180 L0 180 Z"} fill={`url(#${amber ? "amberFill" : "blueFill"})`} /><path d={amber ? "M0 112 C28 106 38 120 67 92 S110 95 137 106 S179 100 209 68 S253 71 281 86 S322 74 347 58 S392 67 420 45 S461 56 500 31" : "M0 104 C28 120 45 91 68 98 S108 74 134 91 S175 60 205 76 S236 64 265 68 S303 45 331 65 S367 52 393 56 S439 26 468 43 S488 34 500 37"} fill="none" stroke={amber ? "#e7b665" : "#62c6e7"} strokeWidth="3" strokeLinecap="round" />{!compact && <circle cx={amber ? "420" : "439"} cy={amber ? "45" : "26"} r="5" fill={amber ? "#e7b665" : "#62c6e7"} stroke="#0c1821" strokeWidth="4" />}</svg>{!compact && <div className="absolute bottom-0 left-0 right-0 flex justify-between text-[10px] text-[#667f8c]"><span>12 Aug</span><span>19 Aug</span><span>26 Aug</span><span>Today</span></div>}</div>; }

function PatientOverview({ go }: { go: (path: string) => void }) { return <><SectionHeading eyebrow="Wednesday, 23 September 2026" title="Good morning, Ananya." copy="A calm check-in is all it takes to keep your health in focus." action={<ActionButton onClick={() => go("/patient/health-check")}><Plus size={16} /> Start health check</ActionButton>} /><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4"><StatCard icon={HeartPulse} label="Latest blood pressure" value="128 / 82" unit="mmHg" detail="Within your usual range" /><StatCard icon={Droplets} label="Latest glucose" value="102" unit="mg/dL" detail="Fasting · 2 days ago" tone="green" /><div className="glass rounded-2xl p-5 md:col-span-2 xl:col-span-2"><div className="flex items-start justify-between"><div><div className="text-xs text-[#829ba7]">Your rhythm</div><div className="mt-2 text-lg font-semibold tracking-[-.03em] text-[#e8f6f8]">3 readings this week</div></div><StatusBadge label="Steady" tone="green" icon={Activity} /></div><div className="mt-3 flex items-center gap-5"><div className="flex -space-x-2">{["M","T","W"].map((day) => <div key={day} className="grid h-7 w-7 place-items-center rounded-full border-2 border-[#101a23] bg-[#20475a] text-[9px] font-semibold text-[#bdebf5]">{day}</div>)}</div><span className="text-xs text-[#8099a5]">You’re building a useful record.</span><TrendChart compact /></div></div></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="glass rounded-2xl p-5 sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><div className="eyebrow">Blood pressure · 30 days</div><h2 className="mt-2 text-xl font-semibold tracking-[-.035em] text-[#e6f4f6]">Your trend, at a glance</h2></div><button onClick={() => go("/patient/history")} className="focus-ring flex items-center gap-1 text-xs font-semibold text-[#69c7e8] hover:text-white">View history <ChevronRight size={14} /></button></div><div className="mt-7"><TrendChart /></div><div className="mt-4 grid grid-cols-3 gap-3 border-t border-[#8bc2d3]/10 pt-4"><MiniMetric label="Average" value="124 / 80" /><MiniMetric label="Highest" value="136 / 86" /><MiniMetric label="Readings" value="12" /></div></div><div className="glass rounded-2xl p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="eyebrow">Next best step</div><h2 className="mt-2 text-xl font-semibold tracking-[-.035em] text-[#e6f4f6]">Keep your rhythm</h2></div><span className="grid h-10 w-10 place-items-center rounded-xl bg-[#163a4d] text-[#71c8e8]"><Sparkles size={18} /></span></div><p className="mt-5 text-sm leading-6 text-[#829aa6]">A reading at a similar time tomorrow will make your trend easier to understand.</p><div className="mt-6 rounded-xl border border-[#78bfd6]/10 bg-[#0c1720] p-4"><div className="flex items-center gap-3"><CalendarDays size={17} className="text-[#6ec6e8]" /><div><div className="text-xs font-semibold text-[#d7edf2]">Suggested check-in</div><div className="mt-1 text-[11px] text-[#7f99a5]">Tomorrow morning · before breakfast</div></div></div></div><ActionButton tone="secondary" className="mt-5 w-full" onClick={() => go("/patient/health-check")}>Set up a reading <ArrowRight size={15} /></ActionButton></div></div><div className="mt-5 flex flex-col gap-3 rounded-2xl border border-[#c08b4b]/20 bg-[#241d18] p-4 sm:flex-row sm:items-center"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-[#443321] text-[#efc174]"><ShieldCheck size={17} /></span><p className="text-xs leading-5 text-[#c8ad8b]"><strong className="text-[#ecd2a9]">A note on these readings:</strong> This demo includes simulated data to show how NovaCare works. It is for awareness and record-keeping, not diagnosis.</p><StatusBadge label="Simulated data" tone="amber" icon={Sparkles} /></div></>; }
function MiniMetric({ label, value }: { label: string; value: string }) { return <div><div className="text-[10px] text-[#6f8995]">{label}</div><div className="mt-1 text-sm font-semibold text-[#d9edf1]">{value}</div></div>; }

function HealthCheck({ go }: { go: (path: string) => void }) { return <><SectionHeading eyebrow="Guided measurement" title="What are we checking today?" copy="Choose a reading to get a calm, step-by-step guide. You can save the result when you’re ready." /><div className="grid gap-4 md:grid-cols-2"><button onClick={() => go("/patient/measure/bp")} className="glass interactive focus-ring group rounded-3xl p-6 text-left"><div className="flex items-start justify-between"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-[#153c4e] text-[#69c9eb]"><HeartPulse size={26} /></span><ArrowRight size={18} className="text-[#5e7b87] transition group-hover:translate-x-1 group-hover:text-[#6bc8e9]" /></div><div className="mt-16 text-xl font-semibold tracking-[-.035em] text-[#e7f6f8]">Blood pressure</div><p className="mt-2 max-w-sm text-sm leading-6 text-[#839ca7]">A cuff-based reference reading with guidance for resting, placing the cuff, and saving your numbers.</p><div className="mt-5 flex items-center gap-2 text-xs text-[#69c8e9]"><Clock3 size={14} /> About 3 minutes</div></button><button onClick={() => go("/patient/measure/glucose")} className="glass interactive focus-ring group rounded-3xl p-6 text-left"><div className="flex items-start justify-between"><span className="grid h-14 w-14 place-items-center rounded-2xl bg-[#173d37] text-[#75dcae]"><Droplets size={26} /></span><ArrowRight size={18} className="text-[#5e7b87] transition group-hover:translate-x-1 group-hover:text-[#75dcae]" /></div><div className="mt-16 text-xl font-semibold tracking-[-.035em] text-[#e7f6f8]">Blood glucose</div><p className="mt-2 max-w-sm text-sm leading-6 text-[#839ca7]">A visual guide for preparing your device, recording the value, and adding meal context.</p><div className="mt-5 flex items-center gap-2 text-xs text-[#75dcae]"><Clock3 size={14} /> About 2 minutes</div></button></div><div className="mt-5 rounded-2xl border border-[#78bfd6]/12 bg-[#0c1720] p-5"><div className="flex items-start gap-3"><Languages size={18} className="mt-0.5 text-[#6ec6e8]" /><div><div className="text-sm font-semibold text-[#e2f4f7]">Prefer another language?</div><p className="mt-1 text-xs leading-5 text-[#8199a5]">The guide can be shown in English, Hindi, Marathi, or Bengali. Change this any time during the flow.</p></div><button onClick={() => toast("Language selector opened in the full product")} className="ml-auto text-xs font-semibold text-[#6cc9e9]">Change</button></div></div></>; }

function MeasurementFlow({ type, go }: { type: "bp" | "glucose"; go: (path: string) => void }) { const [step, setStep] = useState(0); const [saved, setSaved] = useState(false); const isBp = type === "bp"; const steps = isBp ? ["Rest before measuring", "Place the cuff", "Keep your arm supported", "Record your reading"] : ["Wash and dry your hands", "Prepare your device", "Take the reading", "Record your context"]; return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#071019]"><NoiseBackdrop /><div className="relative z-10 mx-auto flex min-h-screen max-w-6xl flex-col px-5 py-5 sm:px-8"><div className="flex items-center justify-between"><button onClick={() => go("/patient/health-check")} className="focus-ring flex items-center gap-2 text-sm text-[#9ab3be] hover:text-white"><ArrowLeft size={16} /> Exit guide</button><div className="flex items-center gap-3"><div className="hidden items-center gap-2 rounded-full border border-[#7bbfd5]/15 bg-[#0d1a23] px-3 py-2 text-xs text-[#8ba5b0] sm:flex"><Languages size={14} className="text-[#69c7e8]" /> English <ChevronDown size={13} /></div><Logo compact /></div></div>{saved ? <div className="flex flex-1 items-center justify-center py-12"><div className="glass blue-glow w-full max-w-lg rounded-3xl p-7 text-center sm:p-10"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-[#194d43] text-[#78e2b5]"><Check size={28} /></span><div className="eyebrow mt-6">Saved to your record</div><h1 className="display-font mt-3 text-5xl tracking-[-.04em] text-[#ebf8fa]">Reading saved.</h1><p className="mx-auto mt-4 max-w-sm text-sm leading-6 text-[#8da7b2]">Your {isBp ? "blood pressure" : "blood glucose"} reading has been added to your history.</p><div className="mt-7 rounded-2xl border border-[#7cbfd5]/12 bg-[#0b1821] p-4 text-left"><div className="flex items-center justify-between"><span className="text-xs text-[#819aa6]">{isBp ? "Blood pressure" : "Blood glucose"}</span><StatusBadge label="Simulated data" tone="amber" icon={Sparkles} /></div><div className="mt-3 text-2xl font-semibold text-[#eaf7f9]">{isBp ? "128 / 82 mmHg" : "102 mg/dL"}</div><div className="mt-1 text-xs text-[#78dbad]">Saved just now · reference reading</div></div><div className="mt-6 flex flex-col gap-2 sm:flex-row"><ActionButton onClick={() => go("/patient/history")} className="flex-1">View history <ArrowRight size={15} /></ActionButton><ActionButton tone="secondary" onClick={() => go("/patient/overview")} className="flex-1">Back to overview</ActionButton></div></div></div> : <><div className="mx-auto flex w-full max-w-3xl flex-1 flex-col justify-center py-10"><div className="mb-10 flex items-center justify-between"><div><div className="eyebrow">{isBp ? "Blood pressure" : "Blood glucose"} · Step {step + 1} of {steps.length}</div><div className="mt-3 h-1.5 w-48 overflow-hidden rounded-full bg-[#17303e] sm:w-72"><div className="h-full rounded-full bg-[#67c6e8] transition-all duration-300" style={{ width: `${((step + 1) / steps.length) * 100}%` }} /></div></div><div className="text-xs font-semibold text-[#89a4af]">{Math.round(((step + 1) / steps.length) * 100)}%</div></div><div className="grid min-h-[420px] items-center gap-8 md:grid-cols-[.9fr_1.1fr]"><div className="relative flex items-center justify-center"><PulseVisual small cuff={isBp && step > 0} /><div className="absolute left-1/2 top-[70%] -translate-x-1/2 whitespace-nowrap rounded-full border border-[#79c2d8]/15 bg-[#0c1821]/80 px-3 py-2 text-[10px] text-[#a2c3cd] backdrop-blur-xl">Camera guide · manual only</div></div><div className="max-w-md"><div className="flex items-center gap-2 text-xs font-semibold text-[#69c7e8]"><span className="grid h-6 w-6 place-items-center rounded-full bg-[#174257] text-[10px]">{step + 1}</span> {step === steps.length - 1 ? "Save your reading" : "Your next step"}</div><h1 className="display-font mt-4 text-5xl leading-[.98] tracking-[-.04em] text-[#ecf8fa] sm:text-6xl">{steps[step]}</h1><p className="mt-5 text-base leading-7 text-[#8da7b2]">{step === 0 ? "Give your body a quiet minute. Sit with both feet on the floor and breathe normally." : step === 1 && isBp ? "Wrap the cuff around your bare upper arm, with the marker aligned to the inside of your elbow." : step === 1 ? "Make sure your meter is ready and your hands are completely dry before you begin." : step === 2 ? "Stay still and let the device complete the reading. NovaCare does not verify technique automatically." : "Enter the value shown by your device. You can add context before saving."}</p>{step === steps.length - 1 ? <div className="mt-7 grid grid-cols-2 gap-3">{isBp ? <><Field label="Systolic" placeholder="128" icon={HeartPulse} /><Field label="Diastolic" placeholder="82" icon={HeartPulse} /></> : <><Field label="Glucose value" placeholder="102" icon={Droplets} /><Field label="Unit" placeholder="mg/dL" icon={Droplets} /></>}</div> : <div className="mt-7 rounded-2xl border border-[#79bdd5]/12 bg-[#0c1821] p-4"><div className="flex items-start gap-3"><Camera size={17} className="mt-0.5 text-[#6ec6e8]" /><div><div className="text-xs font-semibold text-[#dceff3]">Visual guide only</div><div className="mt-1 text-xs leading-5 text-[#8199a5]">This is a manual checklist, not computer vision. If the signal is poor, retry the reading with your device.</div></div></div></div>}<div className="mt-8 flex items-center gap-3"><ActionButton tone="secondary" onClick={() => setStep(Math.max(0, step - 1))} disabled={step === 0}><ArrowLeft size={15} /> Back</ActionButton><ActionButton onClick={() => step === steps.length - 1 ? setSaved(true) : setStep(step + 1)} className="flex-1">{step === steps.length - 1 ? "Save reading" : "Continue"} <ArrowRight size={15} /></ActionButton></div></div></div></div></>}</div></div>; }

const historyRows = [{ date: "23 Sep 2026", time: "08:42", type: "Blood pressure", value: "128 / 82", unit: "mmHg", note: "Morning · seated", tone: "green" as const, tag: "Simulated data" }, { date: "21 Sep 2026", time: "07:58", type: "Blood glucose", value: "102", unit: "mg/dL", note: "Fasting", tone: "green" as const, tag: "Simulated data" }, { date: "19 Sep 2026", time: "18:10", type: "PPG estimate", value: "139 / 91", unit: "mmHg", note: "Experimental sensor path", tone: "amber" as const, tag: "Experimental BP Estimate" }, { date: "17 Sep 2026", time: "09:12", type: "Blood pressure", value: "122 / 78", unit: "mmHg", note: "Morning · seated", tone: "green" as const, tag: "Simulated data" }];
function History({ go }: { go: (path: string) => void }) { return <><SectionHeading eyebrow="Your record" title="History & trends" copy="A record becomes more useful when it is consistent. Review your readings over time." action={<ActionButton tone="secondary" onClick={() => toast("Export is available in the full product")}><FileText size={15} /> Export record</ActionButton>} /><div className="grid gap-5 xl:grid-cols-[1.2fr_.8fr]"><div className="glass rounded-2xl p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="eyebrow">Blood pressure · 30 days</div><h2 className="mt-2 text-xl font-semibold text-[#e7f5f7]">A steady picture</h2></div><div className="flex items-center gap-2 rounded-lg border border-[#81bdd1]/12 bg-[#0c1720] px-2.5 py-2 text-xs text-[#91aab5]"><CalendarDays size={14} /> Last 30 days <ChevronDown size={13} /></div></div><div className="mt-6"><TrendChart /></div><div className="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-[11px] text-[#829aa5]"><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-[#62c6e7]" /> Systolic</span><span className="flex items-center gap-2"><i className="h-2 w-2 rounded-full bg-[#4e7888]" /> Your usual range</span></div></div><div className="glass rounded-2xl p-5 sm:p-6"><div className="eyebrow">Readings by type</div><div className="mt-5 space-y-5"><ReadingType icon={HeartPulse} label="Reference blood pressure" count="12" copy="Cuff-based readings" percent={76} color="blue" /><ReadingType icon={Droplets} label="Blood glucose" count="6" copy="Fasting + post-meal" percent={48} color="green" /><ReadingType icon={Zap} label="Experimental BP Estimate" count="2" copy="PPG path · review carefully" percent={18} color="amber" /></div><div className="mt-6 rounded-xl border border-[#c08b4b]/20 bg-[#251e18] p-3 text-xs leading-5 text-[#c6ad8f]"><strong className="text-[#edd1a7]">Experimental estimate:</strong> This is not equivalent to a cuff reading and should not be used for clinical decisions.</div></div></div><div className="glass mt-5 overflow-hidden rounded-2xl"><div className="flex flex-col gap-3 border-b border-[#84bfd3]/10 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6"><div><div className="eyebrow">All readings</div><h2 className="mt-2 text-xl font-semibold text-[#e7f5f7]">Recent activity</h2></div><div className="flex gap-2"><button className="focus-ring flex items-center gap-2 rounded-lg border border-[#81bdd1]/12 bg-[#0d1821] px-3 py-2 text-xs text-[#8ca6b1]"><Filter size={13} /> Filter</button><button className="focus-ring flex items-center gap-2 rounded-lg border border-[#81bdd1]/12 bg-[#0d1821] px-3 py-2 text-xs text-[#8ca6b1]"><Search size={13} /> Search</button></div></div><div className="overflow-x-auto"><table className="w-full min-w-[720px] text-left text-sm"><thead className="bg-[#0c1720] text-[10px] uppercase tracking-[.14em] text-[#68818e]"><tr><th className="px-6 py-3 font-semibold">Date</th><th className="px-6 py-3 font-semibold">Reading</th><th className="px-6 py-3 font-semibold">Context</th><th className="px-6 py-3 font-semibold">Status</th><th className="px-6 py-3" /></tr></thead><tbody>{historyRows.map((row) => <tr key={row.date + row.time} className="border-t border-[#84bfd3]/8"><td className="px-6 py-4"><div className="font-medium text-[#d9edf1]">{row.date}</div><div className="mt-1 text-xs text-[#718b97]">{row.time}</div></td><td className="px-6 py-4"><div className="font-medium text-[#d9edf1]">{row.type}</div><div className="mt-1 text-xs text-[#78939e]">{row.value} {row.unit}</div></td><td className="px-6 py-4 text-xs text-[#819aa5]">{row.note}</td><td className="px-6 py-4"><StatusBadge label={row.tag} tone={row.tone} icon={row.tone === "amber" ? Zap : Check} /></td><td className="px-6 py-4 text-right"><button onClick={() => toast("Reading details opened")} className="focus-ring text-[#6dc8e8] hover:text-white"><ChevronRight size={16} /></button></td></tr>)}</tbody></table></div><div className="flex items-center justify-between border-t border-[#84bfd3]/8 p-4 text-xs text-[#6f8995]"><span>Showing 1–4 of 20 readings</span><div className="flex gap-1"><button className="focus-ring rounded-lg border border-[#81bdd1]/12 px-2.5 py-1.5 hover:bg-[#122532]">1</button><button className="focus-ring rounded-lg px-2.5 py-1.5 hover:bg-[#122532]">2</button><button className="focus-ring rounded-lg px-2.5 py-1.5 hover:bg-[#122532]">3</button><button className="focus-ring rounded-lg px-2.5 py-1.5 hover:bg-[#122532]"><ArrowRight size={13} /></button></div></div></div></>; }
function ReadingType({ icon: IconComponent, label, count, copy, percent, color }: { icon: Icon; label: string; count: string; copy: string; percent: number; color: "blue" | "green" | "amber" }) { const colors = { blue: "bg-[#62c6e7]", green: "bg-[#62d0a0]", amber: "bg-[#e8b765]" }; return <div><div className="flex items-start gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#172d3a] text-[#8bd3e9]"><IconComponent size={15} /></span><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><span className="truncate text-xs font-semibold text-[#dceff2]">{label}</span><span className="text-sm font-semibold text-[#e4f6f8]">{count}</span></div><div className="mt-1 text-[10px] text-[#748e9a]">{copy}</div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-[#1b2c36]"><div className={`h-full rounded-full ${colors[color]}`} style={{ width: `${percent}%` }} /></div></div></div></div>; }

function SimplePage({ role, page, go }: { role: Role; page: string; go: (path: string) => void }) { const configs: Record<string, { eyebrow: string; title: string; copy: string; icon: Icon }> = { medications: { eyebrow: "Care plan", title: "Medications", copy: "Keep your current medicines and reminders in one calm, easy-to-review place.", icon: Syringe }, profile: { eyebrow: "Your details", title: "Profile", copy: "Review the information that helps your care team understand your context.", icon: UserRound }, settings: { eyebrow: "Preferences", title: "Settings", copy: "Choose your language, notification rhythm, and privacy preferences.", icon: Settings }, "add-patient": { eyebrow: "New patient", title: "Add a patient", copy: "Create a simple record before starting an assisted check.", icon: Plus } }; const config = configs[page] || configs.settings; const IconComponent = config.icon; return <><SectionHeading eyebrow={config.eyebrow} title={config.title} copy={config.copy} action={page === "add-patient" ? <ActionButton onClick={() => toast.success("Patient record saved in demo mode")}><Check size={15} /> Save patient</ActionButton> : undefined} /><div className="grid gap-5 lg:grid-cols-[1fr_.7fr]"><div className="glass rounded-2xl p-5 sm:p-6"><div className="flex items-center gap-3 border-b border-[#83bfd2]/10 pb-5"><span className="grid h-11 w-11 place-items-center rounded-xl bg-[#17394b] text-[#6bc9ea]"><IconComponent size={20} /></span><div><div className="text-sm font-semibold text-[#e4f5f8]">{page === "add-patient" ? "Patient details" : "Your NovaCare profile"}</div><div className="mt-1 text-xs text-[#7b95a1]">Fields marked with * are required</div></div></div><div className="mt-6 grid gap-4 sm:grid-cols-2"><Field label="Full name *" placeholder={role === "asha" ? "Ravi Kumar" : "Ananya Sharma"} icon={UserRound} /><Field label="Phone number *" placeholder="+91 98765 43210" icon={Phone} /><Field label="Village / area" placeholder="Kothur, Telangana" icon={Map} /><Field label="Preferred language" placeholder="English" icon={Languages} /></div>{page === "medications" && <div className="mt-5 rounded-xl border border-[#7fc1d6]/12 bg-[#0b1821] p-4"><div className="flex items-center justify-between"><div><div className="text-sm font-semibold text-[#dcedf1]">Amlodipine 5 mg</div><div className="mt-1 text-xs text-[#7c96a2]">Once daily · Morning</div></div><StatusBadge label="Active" tone="green" /></div></div>}{page === "settings" && <div className="mt-6 space-y-3"><PreferenceRow icon={Languages} title="Language" value="English" /><PreferenceRow icon={Bell} title="Reading reminders" value="Morning, 8:00 AM" /><PreferenceRow icon={Moon} title="Appearance" value="Dark" /></div>}</div><div className="glass rounded-2xl p-5 sm:p-6"><div className="eyebrow">A little reassurance</div><h2 className="mt-3 text-xl font-semibold tracking-[-.03em] text-[#e5f5f8]">Your context matters.</h2><p className="mt-3 text-sm leading-6 text-[#829aa6]">NovaCare keeps the practical details close to your readings, so the next conversation with a health worker or doctor starts with more context.</p><div className="mt-6 flex items-center gap-3 rounded-xl border border-[#74bed6]/12 bg-[#0c1821] p-4"><LockKeyhole size={17} className="text-[#6dc8e9]" /><span className="text-xs leading-5 text-[#8ca5af]">Your profile is shown only inside your role’s private workspace.</span></div></div></div></>; }
function PreferenceRow({ icon: IconComponent, title, value }: { icon: Icon; title: string; value: string }) { return <div className="flex items-center gap-3 rounded-xl border border-[#7fbfd3]/10 bg-[#0b1821] p-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-[#163545] text-[#68c6e8]"><IconComponent size={15} /></span><span className="flex-1 text-xs font-medium text-[#cfe6eb]">{title}</span><span className="text-xs text-[#78939e]">{value}</span><ChevronRight size={14} className="text-[#55717d]" /></div>; }

function AsHAOverview({ go }: { go: (path: string) => void }) { return <><SectionHeading eyebrow="Wednesday, 23 September 2026" title="Good morning, Meera." copy="You have three home visits planned today. Let’s make each one count." action={<ActionButton onClick={() => go("/asha/assisted-check")}><HeartPulse size={16} /> Start assisted check</ActionButton>} /><div className="grid gap-4 md:grid-cols-3"><StatCard icon={UsersRound} label="Patients in your care" value="24" detail="2 need a follow-up" /><StatCard icon={ClipboardList} label="Checks this month" value="68" detail="12% more than August" tone="green" /><StatCard icon={Clock3} label="Next visit" value="10:30" unit="AM" detail="Kothur · Ramesh P." tone="amber" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1fr_.8fr]"><div className="glass rounded-2xl p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="eyebrow">Today’s route</div><h2 className="mt-2 text-xl font-semibold text-[#e7f5f7]">A thoughtful check-in</h2></div><button onClick={() => go("/asha/patients")} className="focus-ring text-xs font-semibold text-[#67c6e8]">View patients <ChevronRight size={14} className="inline" /></button></div><div className="mt-6 space-y-3"><VisitRow time="10:30 AM" name="Ramesh Patel" place="Kothur · BP follow-up" status="Due" tone="amber" /><VisitRow time="1:00 PM" name="Sushila Devi" place="Banjara Hills · New check" status="Upcoming" tone="blue" /><VisitRow time="4:30 PM" name="Farida Begum" place="Kothur · Glucose check" status="Upcoming" tone="blue" /></div></div><div className="glass rounded-2xl p-5 sm:p-6"><div className="eyebrow">Field note</div><h2 className="mt-2 text-xl font-semibold text-[#e7f5f7]">Consistency beats intensity.</h2><p className="mt-4 text-sm leading-6 text-[#829aa6]">A calm, repeatable routine helps a patient build a useful record. NovaCare will never replace your judgment or a doctor’s care.</p><div className="mt-6 flex items-center gap-3 rounded-xl border border-[#73bfd6]/12 bg-[#0c1821] p-4"><Leaf size={18} className="text-[#6fd7aa]" /><span className="text-xs leading-5 text-[#91abb5]">2 patients have not logged a reading in 7 days.</span></div></div></div></>; }
function VisitRow({ time, name, place, status, tone }: { time: string; name: string; place: string; status: string; tone: "amber" | "blue" }) { return <div className="flex items-center gap-3 rounded-xl border border-[#7fbfd3]/10 bg-[#0c1821] p-3"><div className="w-16 text-xs font-semibold text-[#b2cbd3]">{time}</div><div className="h-8 w-px bg-[#73b4c8]/15" /><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold text-[#dceff2]">{name}</div><div className="mt-1 truncate text-[11px] text-[#7b95a1]">{place}</div></div><StatusBadge label={status} tone={tone} icon={tone === "amber" ? Clock3 : CalendarDays} /></div>; }

function PeopleList({ role, go }: { role: Role; go: (path: string) => void }) { const people = role === "doctor" ? [{ initials: "RP", name: "Ramesh Patel", village: "Kothur, Telangana", latest: "128 / 82", status: "GREEN" }, { initials: "SD", name: "Sushila Devi", village: "Banjara Hills, Telangana", latest: "146 / 94", status: "AMBER" }, { initials: "FB", name: "Farida Begum", village: "Kothur, Telangana", latest: "102 mg/dL", status: "GREEN" }, { initials: "AK", name: "Asha Kumari", village: "Narsapur, Telangana", latest: "158 / 101", status: "RED" }] : [{ initials: "RP", name: "Ramesh Patel", village: "Kothur, Telangana", latest: "128 / 82", status: "GREEN" }, { initials: "SD", name: "Sushila Devi", village: "Banjara Hills, Telangana", latest: "146 / 94", status: "AMBER" }, { initials: "FB", name: "Farida Begum", village: "Kothur, Telangana", latest: "102 mg/dL", status: "GREEN" }]; return <><SectionHeading eyebrow={role === "doctor" ? "Patient records" : "Your care list"} title="Patients" copy={role === "doctor" ? "Search patient records and review their reading history with context." : "Find a patient to review their record or start an assisted check."} action={role === "asha" ? <ActionButton onClick={() => go("/asha/add-patient")}><Plus size={15} /> Add patient</ActionButton> : <ActionButton tone="secondary" onClick={() => toast("Bulk export is available in the full product")}><FileText size={15} /> Export list</ActionButton>} /><div className="glass overflow-hidden rounded-2xl"><div className="flex flex-col gap-3 border-b border-[#84bfd3]/10 p-5 sm:flex-row sm:items-center sm:justify-between sm:p-6"><div className="relative w-full max-w-sm"><Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#617d89]" /><input className="focus-ring h-11 w-full rounded-xl border border-[#7fbfd3]/12 bg-[#0b1720] pl-10 pr-4 text-sm text-[#dceff3] placeholder:text-[#5d7783]" placeholder="Search by name or patient ID" /></div><div className="flex gap-2"><button className="focus-ring flex items-center gap-2 rounded-lg border border-[#7fbfd3]/12 bg-[#0b1720] px-3 py-2.5 text-xs text-[#8da6b0]"><Filter size={13} /> Filter</button><div className="flex items-center rounded-lg border border-[#7fbfd3]/12 bg-[#0b1720] px-3 text-xs text-[#78939f]">{people.length + (role === "asha" ? 21 : 0)} total</div></div></div><div className="divide-y divide-[#84bfd3]/8">{people.map((person) => <button key={person.name} onClick={() => toast(`${person.name}'s record opened in demo mode`)} className="focus-ring flex w-full items-center gap-4 p-5 text-left transition hover:bg-[#0e1d27] sm:px-6"><div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-[#1a3b4b] text-xs font-semibold text-[#9fe1f0]">{person.initials}</div><div className="min-w-0 flex-1"><div className="text-sm font-semibold text-[#deeff2]">{person.name}</div><div className="mt-1 text-xs text-[#78939f]">{person.village} · ID NC-{person.initials}204</div></div><div className="hidden text-right sm:block"><div className="text-[10px] text-[#69838e]">Latest reading</div><div className="mt-1 text-sm font-semibold text-[#d9edf1]">{person.latest}</div></div><StatusBadge label={person.status} tone={person.status === "GREEN" ? "green" : person.status === "AMBER" ? "amber" : "red"} icon={person.status === "GREEN" ? Check : person.status === "AMBER" ? CircleHelp : Zap} /><ChevronRight size={16} className="text-[#55727f]" /></button>)}</div><div className="flex items-center justify-between border-t border-[#84bfd3]/8 p-4 text-xs text-[#708b97]"><span>Showing {people.length} recent records</span><button className="focus-ring text-[#69c7e8]">View all patients <ArrowRight size={13} className="inline" /></button></div></div></>; }

function AssistedCheck({ go }: { go: (path: string) => void }) { return <><SectionHeading eyebrow="Field workflow" title="Start an assisted check" copy="Choose a patient and NovaCare will guide you through the same calm measurement flow." /><div className="grid gap-5 lg:grid-cols-[.8fr_1.2fr]"><div className="glass rounded-2xl p-5 sm:p-6"><div className="eyebrow">Step 1 of 2</div><h2 className="mt-3 text-xl font-semibold text-[#e7f5f7]">Choose a patient</h2><div className="relative mt-5"><Search size={16} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[#617d89]" /><input className="focus-ring h-12 w-full rounded-xl border border-[#7fbfd3]/12 bg-[#0b1720] pl-10 pr-4 text-sm text-[#dceff3] placeholder:text-[#5d7783]" placeholder="Search patient ID" /></div><div className="mt-4 space-y-2"><button className="focus-ring flex w-full items-center gap-3 rounded-xl border border-[#65c5e8]/35 bg-[#143345] p-3 text-left"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#23556b] text-xs font-semibold text-[#b4edf8]">RP</div><div className="flex-1"><div className="text-xs font-semibold text-[#e1f4f7]">Ramesh Patel</div><div className="mt-1 text-[10px] text-[#82a1ad]">NC-RP204 · Kothur</div></div><Check size={16} className="text-[#68d4aa]" /></button>{["Sushila Devi · NC-SD204", "Farida Begum · NC-FB204"].map((name) => <button key={name} onClick={() => toast("Patient selected")} className="focus-ring flex w-full items-center gap-3 rounded-xl border border-[#79bdd3]/10 bg-[#0c1821] p-3 text-left hover:bg-[#102431]"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#1b3441] text-[10px] font-semibold text-[#9dd8e7]">{name.slice(0,2)}</div><span className="text-xs text-[#b8d0d8]">{name}</span><ChevronRight size={14} className="ml-auto text-[#55717f]" /></button>)}</div></div><div className="glass relative overflow-hidden rounded-2xl p-6 sm:p-8"><div className="absolute right-[-8rem] top-[-7rem] h-72 w-72 rounded-full bg-[#278eb9]/10 blur-3xl" /><div className="relative z-10"><div className="flex items-start justify-between"><div><div className="eyebrow">Step 2 of 2</div><h2 className="mt-3 text-2xl font-semibold tracking-[-.035em] text-[#e7f5f7]">Select a check</h2><p className="mt-2 text-sm text-[#829aa6]">You’re checking in with Ramesh Patel.</p></div><PulseVisual small cuff /></div><div className="mt-5 grid gap-3 sm:grid-cols-2"><button onClick={() => go("/asha/assisted-check/measure-bp")} className="focus-ring interactive rounded-2xl border border-[#69c7e8]/20 bg-[#123142] p-4 text-left"><HeartPulse size={20} className="text-[#69c9eb]" /><div className="mt-8 text-sm font-semibold text-[#e0f3f6]">Blood pressure</div><div className="mt-1 text-xs text-[#84a1ad]">Cuff reference check</div></button><button onClick={() => toast("Glucose guide selected")} className="focus-ring interactive rounded-2xl border border-[#70cda5]/15 bg-[#13312e] p-4 text-left"><Droplets size={20} className="text-[#73d8ad]" /><div className="mt-8 text-sm font-semibold text-[#e0f3f6]">Blood glucose</div><div className="mt-1 text-xs text-[#84a1ad]">Record a glucose value</div></button></div></div></div></div></>; }

function DoctorOverview({ go }: { go: (path: string) => void }) { return <><SectionHeading eyebrow="Wednesday, 23 September 2026" title="Good morning, Dr. Rao." copy="Here’s the community signal across your connected villages." action={<ActionButton onClick={() => go("/doctor/patients")}><UsersRound size={16} /> View patient records</ActionButton>} /><div className="grid gap-4 md:grid-cols-4"><StatCard icon={UsersRound} label="Connected patients" value="142" detail="Across 6 villages" /><StatCard icon={HeartPulse} label="Readings this week" value="318" detail="87% have a 7-day rhythm" tone="green" /><StatCard icon={CircleHelp} label="Needs attention" value="18" detail="12 amber · 6 red" tone="amber" /><StatCard icon={Map} label="Villages active" value="6 / 6" detail="All reporting this month" /></div><div className="mt-5 grid gap-5 xl:grid-cols-[1.15fr_.85fr]"><div className="glass rounded-2xl p-5 sm:p-6"><div className="flex items-center justify-between"><div><div className="eyebrow">Community pulse</div><h2 className="mt-2 text-xl font-semibold text-[#e7f5f7]">Risk tier movement</h2></div><button onClick={() => go("/doctor/heatmap")} className="focus-ring text-xs font-semibold text-[#69c7e8]">Open heatmap <ChevronRight size={14} className="inline" /></button></div><div className="mt-6"><TrendChart amber /></div><div className="mt-5 flex flex-wrap gap-2"><StatusBadge label="18 RED" tone="red" icon={Zap} /><StatusBadge label="42 AMBER" tone="amber" icon={CircleHelp} /><StatusBadge label="82 GREEN" tone="green" icon={Check} /></div></div><div className="glass rounded-2xl p-5 sm:p-6"><div className="eyebrow">Needs a closer look</div><h2 className="mt-2 text-xl font-semibold text-[#e7f5f7]">Priority patients</h2><div className="mt-5 space-y-3"><PriorityRow initials="AK" name="Asha Kumari" detail="158 / 101 · 2 elevated readings" tone="red" /><PriorityRow initials="SD" name="Sushila Devi" detail="146 / 94 · no reading in 5 days" tone="amber" /><PriorityRow initials="VN" name="Vijay Naidu" detail="PPG estimate only · needs cuff check" tone="amber" /></div></div></div></>; }
function PriorityRow({ initials, name, detail, tone }: { initials: string; name: string; detail: string; tone: "red" | "amber" }) { return <button onClick={() => toast(`${name}'s record opened`)} className="focus-ring flex w-full items-center gap-3 rounded-xl border border-[#7fbfd3]/10 bg-[#0c1821] p-3 text-left hover:bg-[#11222d]"><div className="grid h-9 w-9 place-items-center rounded-xl bg-[#3a2525] text-[10px] font-semibold text-[#ffb2a9]">{initials}</div><div className="min-w-0 flex-1"><div className="text-xs font-semibold text-[#e0f1f4]">{name}</div><div className="mt-1 truncate text-[10px] text-[#809aa5]">{detail}</div></div><StatusBadge label={tone === "red" ? "RED" : "AMBER"} tone={tone} icon={tone === "red" ? Zap : CircleHelp} /></button>; }

function Heatmap() { const villages = [{ name: "Kothur", x: 26, y: 32, risk: "green", count: 42 }, { name: "Banjara Hills", x: 57, y: 24, risk: "amber", count: 31 }, { name: "Narsapur", x: 74, y: 49, risk: "red", count: 18 }, { name: "Medchal", x: 38, y: 63, risk: "green", count: 25 }, { name: "Shamirpet", x: 67, y: 72, risk: "amber", count: 14 }, { name: "Ghatkesar", x: 21, y: 79, risk: "green", count: 12 }]; return <><SectionHeading eyebrow="Community signal" title="Village heatmap" copy="A high-level view of risk tiers across your connected communities. Use it to decide where to look closer, not to diagnose." action={<ActionButton tone="secondary"><CalendarDays size={15} /> 01–23 Sep 2026 <ChevronDown size={13} /></ActionButton>} /><div className="mb-5 flex flex-wrap gap-2"><div className="flex items-center gap-2 rounded-xl border border-[#7cbfd3]/10 bg-[#0d1922] px-3 py-2 text-xs text-[#9db5bf]"><Filter size={14} className="text-[#67c6e8]" /> All districts <ChevronDown size={13} /></div><div className="flex items-center gap-2 rounded-xl border border-[#7cbfd3]/10 bg-[#0d1922] px-3 py-2 text-xs text-[#9db5bf]">All risk tiers <ChevronDown size={13} /></div><div className="ml-auto flex items-center gap-2 rounded-xl border border-[#c18f50]/20 bg-[#2a2118] px-3 py-2 text-xs text-[#e0bf89]"><ShieldCheck size={14} /> 142 patients across 6 villages</div></div><div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]"><div className="glass relative min-h-[520px] overflow-hidden rounded-2xl p-5 sm:p-7"><div className="absolute inset-0 opacity-20" style={{ backgroundImage: "linear-gradient(rgba(110,190,214,.18) 1px, transparent 1px), linear-gradient(90deg, rgba(110,190,214,.18) 1px, transparent 1px)", backgroundSize: "44px 44px" }} /><svg className="absolute inset-[10%] h-[80%] w-[80%] opacity-35" viewBox="0 0 600 440" preserveAspectRatio="none"><path d="M70 20 L200 75 L155 160 L250 205 L205 300 L330 360 L430 275 L520 325 L560 195 L460 160 L495 70 L350 90 L280 30 Z" fill="none" stroke="#6dbdd6" strokeWidth="2" strokeDasharray="8 10" /><path d="M180 75 C255 125 260 175 330 205 S415 225 495 285" fill="none" stroke="#6dbdd6" strokeOpacity=".5" strokeWidth="2" /></svg><div className="relative z-10 flex items-center justify-between"><div><div className="eyebrow">Telangana · community view</div><div className="mt-2 text-sm text-[#8da8b3]">Risk tiers from recent readings</div></div><div className="flex items-center gap-3 text-[10px] text-[#89a5b0]"><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#65d1a5]" /> Green</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#edbd69]" /> Amber</span><span className="flex items-center gap-1.5"><i className="h-2 w-2 rounded-full bg-[#ef776e]" /> Red</span></div></div>{villages.map((v) => <button key={v.name} onClick={() => toast(`${v.name}: ${v.count} patients in demo data`)} style={{ left: `${v.x}%`, top: `${v.y}%` }} className="focus-ring absolute z-20 -translate-x-1/2 -translate-y-1/2 text-left"><span className={`pulse-ring absolute -inset-3 rounded-full ${v.risk === "green" ? "bg-[#55c99b]/15" : v.risk === "amber" ? "bg-[#e5b460]/18" : "bg-[#ed7068]/20"}`} /><span className={`relative grid h-8 w-8 place-items-center rounded-full border-2 ${v.risk === "green" ? "border-[#63d3a7] bg-[#1d5948] text-[#b2f0d2]" : v.risk === "amber" ? "border-[#e4b566] bg-[#5a4526] text-[#f9d58c]" : "border-[#ef786f] bg-[#672f31] text-[#ffc0b9]"}`}><Map size={14} /></span><span className="absolute left-10 top-1/2 hidden -translate-y-1/2 whitespace-nowrap rounded-lg border border-[#77b9ca]/15 bg-[#0a151d]/90 px-2.5 py-1.5 text-[10px] text-[#c4dce3] backdrop-blur-md sm:block">{v.name} · {v.count}</span></button>)}<div className="absolute bottom-5 left-5 rounded-xl border border-[#7dbbd0]/12 bg-[#0c1821]/80 px-3 py-2 text-[10px] text-[#77939f] backdrop-blur">Illustrative map · not for emergency triage</div></div><div className="space-y-5"><div className="glass rounded-2xl p-5"><div className="eyebrow">Summary</div><h2 className="mt-3 text-2xl font-semibold tracking-[-.04em] text-[#e8f6f8]">The signal is mostly steady.</h2><p className="mt-3 text-sm leading-6 text-[#849ca8]">Most connected patients are in the green tier. Two clusters would benefit from a closer look this week.</p><div className="mt-6 space-y-3"><RiskBar label="GREEN · Low" count="82" width={58} tone="green" /><RiskBar label="AMBER · Medium" count="42" width={30} tone="amber" /><RiskBar label="RED · High" count="18" width={13} tone="red" /></div></div><div className="rounded-2xl border border-[#c18f50]/18 bg-[#251e18] p-5"><div className="flex items-start gap-3"><CircleHelp size={18} className="mt-0.5 text-[#edc174]" /><div><div className="text-sm font-semibold text-[#ecd2a9]">Use tiers as a prompt</div><p className="mt-2 text-xs leading-5 text-[#c1a986]">Risk tiers organize attention from recorded data. They do not diagnose a patient or replace clinical judgement.</p></div></div></div></div></div></>; }
function RiskBar({ label, count, width, tone }: { label: string; count: string; width: number; tone: "green" | "amber" | "red" }) { const color = { green: "bg-[#63d3a7]", amber: "bg-[#e4b566]", red: "bg-[#ef786f]" }[tone]; return <div><div className="flex justify-between text-xs"><span className="text-[#b8cfd5]">{label}</span><span className="font-semibold text-[#e5f4f7]">{count}</span></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-[#1c2a31]"><div className={`h-full rounded-full ${color}`} style={{ width: `${width}%` }} /></div></div>; }

function Dashboard({ role, path, go }: { role: Role; path: string; go: (path: string) => void }) { const page = path.split("/")[2] || "overview"; const content = useMemo(() => { if (path.includes("/measure")) return (role === "patient" || role === "asha") ? <MeasurementFlow type={path.includes("glucose") ? "glucose" : "bp"} go={go} /> : null; if (role === "patient") { if (page === "overview") return <PatientOverview go={go} />; if (page === "health-check") return <HealthCheck go={go} />; if (page === "history") return <History go={go} />; return <SimplePage role={role} page={page} go={go} />; } if (role === "asha") { if (page === "overview") return <AsHAOverview go={go} />; if (page === "patients") return <PeopleList role={role} go={go} />; if (page === "assisted-check") return <AssistedCheck go={go} />; return <SimplePage role={role} page={page} go={go} />; } if (page === "overview") return <DoctorOverview go={go} />; if (page === "patients") return <PeopleList role={role} go={go} />; if (page === "heatmap") return <Heatmap />; return <DoctorOverview go={go} />; }, [go, page, path, role]); return <AppShell role={role} path={path} go={go}>{content}</AppShell>; }

export default function Home() { const { path, go } = useRouter(); if (path === "/" || path === "") return <Landing go={go} />; if (path === "/roles") return <Roles go={go} />; if (path.startsWith("/login/")) return <Login role={(path.split("/")[2] as Role) || "patient"} go={go} />; const role = path.startsWith("/asha") ? "asha" : path.startsWith("/doctor") ? "doctor" : "patient"; return <Dashboard role={role} path={path} go={go} />; }
